SELECT CAST(COUNT(CASE WHEN p.gender = 'M' AND EXTRACT(YEAR FROM AGE(p.anchor_year)) = 58 AND d.icd_code IN ('44345005', '44345006') AND e.infusion_type = 'IV' AND e.starttime BETWEEN a.intime AND a.intime + INTERVAL '24 hours' AND e.endtime BETWEEN a.dischtime - INTERVAL '12 hours' THEN 1 END) AS FLOAT) / NULLIF(COUNT(a.subject_id), 0) AS proportion FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id JOIN emar_detail e ON a.subject_id = e.subject_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM AGE(p.anchor_year)) = 58 AND d.icd_code IN ('44345005', '44345006') AND e.infusion_type = 'IV';